//! Per-host token resolution for the platform layer.
//! (Generated by v0.6.0 Step 3 Phase 1)
//!
//! Mirrors [`crate::github::auth`]: env var wins, then a platform CLI, result
//! cached per host. `GitHub` (github.com) uses `GITHUB_TOKEN` → `gh auth token`;
//! `GitLab` (gitlab.com) uses `GITLAB_TOKEN` → `glab auth token`; `Gitea`
//! (gitea.com) is env-only (`GITEA_TOKEN`). Self-hosted hosts try
//! `FAMILY_<HOST>_TOKEN` (host upper-snake) for every family, since the family
//! cannot be inferred from the host alone.

use std::collections::HashMap;
use std::sync::{Mutex, OnceLock};

use secrecy::SecretString;

use super::error::PlatformError;
use super::remote::PlatformKind;

/// Per-host token cache, lazily initialized once per process.
static TOKENS: OnceLock<Mutex<HashMap<String, SecretString>>> = OnceLock::new();

fn token_store() -> &'static Mutex<HashMap<String, SecretString>> {
    TOKENS.get_or_init(|| Mutex::new(HashMap::new()))
}

/// Resolve a token for `host`/`kind`, caching the result per host.
pub fn resolve_token(host: &str, kind: PlatformKind) -> Result<SecretString, PlatformError> {
    if let Some(t) = token_store().lock().unwrap().get(host) {
        return Ok(t.clone());
    }
    let raw = pick_token(kind, host, env_token(host, kind), cli_token(kind))?;
    let secret = SecretString::new(raw.into_boxed_str());
    token_store()
        .lock()
        .unwrap()
        .insert(host.to_string(), secret.clone());
    Ok(secret)
}

/// Pure precedence: env token wins; empty env falls back to CLI; both absent or
/// empty yields a guided [`PlatformError::Token`]. Injectable for unit tests.
pub(crate) fn pick_token(
    kind: PlatformKind,
    host: &str,
    env: Option<String>,
    cli: Result<String, String>,
) -> Result<String, PlatformError> {
    if let Some(t) = env {
        if !t.is_empty() {
            return Ok(t);
        }
    }
    let (label, env_var) = env_info(host, kind);
    let cli_name = cli_name(kind);
    match cli {
        Ok(t) if !t.is_empty() => Ok(t),
        Ok(_) => Err(PlatformError::Token(format!(
            "{cli_name} auth token 为空，请设置 {env_var} 环境变量"
        ))),
        Err(_) => Err(PlatformError::Token(format!(
            "{cli_name} 不可用，无法自动获取 {label} token；设置 {env_var} 环境变量后重试"
        ))),
    }
}

/// Resolve the env-var name + label used in user-facing messages.
fn env_info(host: &str, kind: PlatformKind) -> (String, String) {
    match kind {
        PlatformKind::GitHub => ("GitHub".into(), "GITHUB_TOKEN".into()),
        PlatformKind::GitLab => ("GitLab".into(), "GITLAB_TOKEN".into()),
        PlatformKind::Gitea => ("Gitea".into(), "GITEA_TOKEN".into()),
        PlatformKind::SelfHosted => {
            let h = host_env_var(host);
            let var = format!("`GITHUB_{h}_TOKEN` / `GITLAB_{h}_TOKEN` / `GITEA_{h}_TOKEN`");
            ("SelfHosted".into(), var)
        }
    }
}

/// CLI binary name (or sentinel) for user-facing messages.
fn cli_name(kind: PlatformKind) -> &'static str {
    match kind {
        PlatformKind::GitHub => "gh",
        PlatformKind::GitLab => "glab",
        // Gitea has no standard CLI for token resolution; self-hosted relies on env.
        PlatformKind::Gitea | PlatformKind::SelfHosted => "CLI",
    }
}

/// Read the env-var token for `host`/`kind`.
///
/// SaaS hosts check only their family var; self-hosted checks all three family
/// vars so the first set var disambiguates the platform.
fn env_token(host: &str, kind: PlatformKind) -> Option<String> {
    let families = env_families(kind);
    for family in families {
        let name = if matches!(kind, PlatformKind::SelfHosted) {
            format!("{family}_{}_TOKEN", host_env_var(host))
        } else {
            format!("{family}_TOKEN")
        };
        if let Ok(t) = std::env::var(&name) {
            if !t.is_empty() {
                return Some(t);
            }
        }
    }
    None
}

fn env_families(kind: PlatformKind) -> &'static [&'static str] {
    match kind {
        PlatformKind::GitHub => &["GITHUB"],
        PlatformKind::GitLab => &["GITLAB"],
        PlatformKind::Gitea => &["GITEA"],
        PlatformKind::SelfHosted => &["GITHUB", "GITLAB", "GITEA"],
    }
}

/// `git.example.com` → `GIT_EXAMPLE_COM` (upper-snake, port-safe).
fn host_env_var(host: &str) -> String {
    host.to_uppercase().replace(['.', ':'], "_")
}

/// Run the platform CLI to fetch a token (`gh`/`glab` for SaaS only).
fn cli_token(kind: PlatformKind) -> Result<String, String> {
    match kind {
        PlatformKind::GitHub => cli_gh_token(),
        PlatformKind::GitLab => cli_glab_token(),
        PlatformKind::Gitea | PlatformKind::SelfHosted => Err("CLI 不可用".into()),
    }
}

fn cli_gh_token() -> Result<String, String> {
    let out = std::process::Command::new("gh")
        .args(["auth", "token"])
        .output()
        .map_err(|e| format!("gh 不可用：{e}"))?;
    if !out.status.success() {
        return Err(format!(
            "gh auth token 失败（未登录？）：{}",
            String::from_utf8_lossy(&out.stderr).trim()
        ));
    }
    let t = String::from_utf8(out.stdout).map_err(|e| format!("输出非 UTF-8：{e}"))?;
    Ok(t.trim().to_string())
}

fn cli_glab_token() -> Result<String, String> {
    let out = std::process::Command::new("glab")
        .args(["auth", "token"])
        .output()
        .map_err(|e| format!("glab 不可用：{e}"))?;
    if !out.status.success() {
        return Err(format!(
            "glab auth token 失败（未登录？）：{}",
            String::from_utf8_lossy(&out.stderr).trim()
        ));
    }
    let t = String::from_utf8(out.stdout).map_err(|e| format!("输出非 UTF-8：{e}"))?;
    Ok(t.trim().to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn host_env_var_normalizes() {
        assert_eq!(host_env_var("git.example.com"), "GIT_EXAMPLE_COM");
        assert_eq!(host_env_var("git.example.com:8080"), "GIT_EXAMPLE_COM_8080");
    }

    #[test]
    fn env_families_restrict_saas() {
        assert_eq!(env_families(PlatformKind::GitHub), &["GITHUB"]);
        assert_eq!(env_families(PlatformKind::GitLab), &["GITLAB"]);
        assert_eq!(env_families(PlatformKind::Gitea), &["GITEA"]);
        assert_eq!(
            env_families(PlatformKind::SelfHosted),
            &["GITHUB", "GITLAB", "GITEA"]
        );
    }

    #[test]
    fn cli_name_per_kind() {
        assert_eq!(cli_name(PlatformKind::GitHub), "gh");
        assert_eq!(cli_name(PlatformKind::GitLab), "glab");
        assert_eq!(cli_name(PlatformKind::Gitea), "CLI");
        assert_eq!(cli_name(PlatformKind::SelfHosted), "CLI");
    }

    #[test]
    fn env_info_saas_vars() {
        assert_eq!(
            env_info("github.com", PlatformKind::GitHub),
            ("GitHub".into(), "GITHUB_TOKEN".into())
        );
        assert_eq!(
            env_info("gitlab.com", PlatformKind::GitLab),
            ("GitLab".into(), "GITLAB_TOKEN".into())
        );
        assert_eq!(
            env_info("gitea.com", PlatformKind::Gitea),
            ("Gitea".into(), "GITEA_TOKEN".into())
        );
    }

    #[test]
    fn pick_token_env_wins() {
        let t = pick_token(
            PlatformKind::GitLab,
            "gitlab.com",
            Some("glpat_env".into()),
            Ok("glpat_cli".into()),
        )
        .expect("env wins");
        assert_eq!(t, "glpat_env");
    }

    #[test]
    fn pick_token_cli_fallback_when_env_empty() {
        let t = pick_token(
            PlatformKind::GitLab,
            "gitlab.com",
            Some(String::new()),
            Ok("glpat_cli".into()),
        )
        .expect("empty env falls back to cli");
        assert_eq!(t, "glpat_cli");
    }

    #[test]
    fn pick_token_empty_cli_is_error() {
        let err =
            pick_token(PlatformKind::GitHub, "github.com", None, Ok(String::new())).unwrap_err();
        assert!(matches!(err, PlatformError::Token(_)));
    }

    #[test]
    fn pick_token_no_env_no_cli_is_error() {
        let err = pick_token(
            PlatformKind::Gitea,
            "gitea.com",
            None,
            Err("CLI 不可用".into()),
        )
        .unwrap_err();
        assert!(matches!(err, PlatformError::Token(_)));
        assert!(err.to_string().contains("GITEA_TOKEN"));
    }
}
